import {REJECTION_COPY} from './rejection-copy.js?v=5.19.0';
import {liveReasons,liveReasonLabel} from './live-rejection.js?v=5.30.1';
import {LANGS,formatMoney} from './locale.js?v=5.6.0';
import {PROPOSAL_COPY} from './proposal-copy.js?v=5.21.0';
import {NEGOTIATION_COPY} from './negotiation-copy.js?v=5.21.0';
import {AMENDMENT_COPY} from './amendment-copy.js?v=5.19.0';
import {esc} from './core.js?v=5.6.0';
const c=l=>AMENDMENT_COPY[l]||AMENDMENT_COPY.en;
const ownerName={ko:'사장님',en:'Owner',vi:'Chủ quán',zh:'店主',ja:'オーナー',km:'ម្ចាស់ហាង',id:'Pemilik',lo:'ເຈົ້າຂອງ',hi:'मालिक'};
const dataSummary=(data,lang)=>data?.lines?data.lines.map(x=>`${x.name?.[lang]||x.name?.ko||x.itemId} × ${x.quantity}`).join(' · '):data?.date?`${data.date} ${String(data.time).slice(0,5)} · ${data.partySize}`:'';
export const pendingAmendment=(items,id)=>(items||[]).find(x=>x.target_id===id&&x.status==='pending');
const sendOffer={ko:'거절하고 대안 제안',en:'Decline and offer an alternative',vi:'Từ chối và đề xuất món khác',zh:'拒绝并提出替代方案',ja:'お断りして代替案を提案',km:'បដិសេធ និងស្នើជម្រើសផ្សេង',id:'Tolak dan tawarkan pilihan lain',lo:'ປະຕິເສດ ແລະສະເໜີທາງເລືອກ',hi:'अस्वीकार करके दूसरा विकल्प दें'};
const fields={ko:['대안 메뉴','수량','날짜','시간'],en:['Alternative item','Quantity','Date','Time'],vi:['Món thay thế','Số lượng','Ngày','Giờ'],zh:['替代菜品','数量','日期','时间'],ja:['代替メニュー','数量','日付','時間'],km:['ម្ហូបជំនួស','ចំនួន','កាលបរិច្ឆេទ','ម៉ោង'],id:['Menu pengganti','Jumlah','Tanggal','Waktu'],lo:['ເມນູທົດແທນ','ຈຳນວນ','ວັນທີ','ເວລາ'],hi:['वैकल्पिक व्यंजन','मात्रा','तारीख','समय']};
function rejectionForm(a,lang,staff=false,menu=[]){const rc=REJECTION_COPY[lang]||REJECTION_COPY.en,pc=PROPOSAL_COPY[lang]||PROPOSAL_COPY.en,f=fields[lang]||fields.en,id='reason-'+a.id,options=menu.filter(x=>x.available!==false);const offer=a.kind==='change'?`<label class="offer-toggle"><input type="checkbox" name="offer" value="yes"> ${esc(pc.title)}</label><div class="offer-fields"><small>${esc(pc.proposed)}</small>${a.target_type==='order'?`<label>${esc(f[0])}<select name="itemId"><option value="">—</option>${options.map(x=>`<option value="${esc(x.id)}">${esc(x.name?.[lang]||x.name?.ko||x.id)}</option>`).join('')}</select></label><label>${esc(f[1])}<input type="number" name="quantity" min="1" max="20" value="1"></label>`:`<label>${esc(f[2])}<input type="date" name="date" value="${esc(a.after_data?.date||'')}"></label><label>${esc(f[3])}<input type="time" name="time" value="${esc(a.after_data?.time||'')}"></label>`}</div>`:'';return `<details class="amend-reject" data-reject-id="${esc(a.id)}"><summary>${esc(c(lang).reject)}</summary><form data-form="${staff?'staff-amend-reject':'amend-reject'}" data-type="${esc(a.target_type)}" data-request="${esc(a.id)}" data-guest-lang="${esc(a.guest_lang||'ko')}"><label for="${esc(id)}">${esc(rc.reason)}</label><select id="${esc(id)}" name="reason" required><option value="">${esc(rc.choose)}</option>${liveReasons(a).map(reason=>`<option value="${esc(reason)}">${esc(liveReasonLabel(reason,lang))}</option>`).join('')}</select><small>${esc(rc.preview)}</small><p data-reason-preview aria-live="polite"></p>${offer}<button class="button" type="submit" data-reject-label="${esc(c(lang).reject)}" data-offer-label="${esc(sendOffer[lang]||sendOffer.en)}">${esc(c(lang).reject)}</button></form></details>`;}
function proposalMarkup(a,lang,owner=false){if(!a.proposal_data)return '';const pc=PROPOSAL_COPY[lang]||PROPOSAL_COPY.en,guest=LANGS[a.guest_lang]?a.guest_lang:'ko',p=a.proposal_data;const desc=l=>dataSummary(p,l)+(p.total!==undefined?' · '+formatMoney(p.total,l):'');return `<div class="amend-proposal"><strong>${esc(pc.title)} · ${esc(pc[a.proposal_status]||pc.pending)}</strong><p>${esc(pc.proposed)}: ${esc(desc(lang))}</p>${owner&&guest!=='ko'?`<small>${esc(LANGS[guest])}</small><p lang="${esc(guest)}">${esc(desc(guest))}</p>`:''}${a.proposal_at?`<small>${esc(new Date(a.proposal_at).toLocaleString(lang))}</small>`:''}${a.proposal_responded_at?`<small>${esc(pc.response)} · ${esc(new Date(a.proposal_responded_at).toLocaleString(lang))}</small>`:''}</div>`;}
function ownerAudit(a){if(a.status!=='rejected'&&!a.proposal_data&&!a.parent_amendment_id)return '';const guest=LANGS[a.guest_lang]?a.guest_lang:'ko',data=a.kind==='change'?a.after_data:a.before_data;const request=l=>`${c(l)[a.kind]} · ${dataSummary(data,l)}`;const rc=REJECTION_COPY.ko;return `<div class="amend-bilingual"><small>${esc(rc.request)} · ${esc(rc.korean)}</small><p lang="ko">${esc(request('ko'))}</p>${guest!=='ko'?`<small>${esc(rc.request)} · ${esc(LANGS[guest])} · ${esc(rc.original)}</small><p lang="${esc(guest)}">${esc(request(guest))}</p>`:''}${a.reason_messages?.ko?`<small>${esc(rc.korean)}</small><p lang="ko">${esc(a.reason_messages.ko)}</p>${guest!=='ko'&&a.reason_messages[guest]?`<small>${esc(rc.original)} · ${esc(LANGS[guest])}</small><p lang="${esc(guest)}">${esc(a.reason_messages[guest])}</p>`:''}`:''}</div>`;}

function editInputs(type,source,menu,lang,labels){return type==='order'?menu.filter(x=>x.available!==false).map(x=>`<label class="amend-line"><span>${esc(x.name?.[lang]||x.name?.ko||x.id)}${Number.isFinite(Number(x.price))?` <small>${esc(formatMoney(x.price,lang))}</small>`:''}</span><input type="number" name="item-${esc(x.id)}" min="0" max="20" step="1" value="${source.lines?.find(l=>l.itemId===x.id)?.quantity||0}" aria-label="${esc(x.name?.[lang]||x.name?.ko||x.id)}"></label>`).join(''):`<label>${esc(labels.date)}<input type="date" name="date" value="${esc(source.date)}" required></label><label>${esc(labels.time)}<input type="time" name="time" value="${esc(String(source.time).slice(0,5))}" required></label><label>${esc(labels.party)}<input type="number" name="partySize" min="1" max="20" value="${esc(source.partySize)}" required></label>`;}
function requestStatus(a,lang){const n=NEGOTIATION_COPY[lang]||NEGOTIATION_COPY.en;return a.parent_amendment_id?(a.status==='pending'?n.waiting:a.status==='approved'?n.agreed:c(lang).rejected):c(lang)[a.status==='pending'?'pending':a.status==='rejected'?'rejected':a.kind==='cancel'?'cancelled':'changed'];}

export function amendmentMarkup({items=[],record,type,lang='ko',owner=false,menu=[],local=false,labels={date:'Date',time:'Time',party:'Guests'}}){
 if(local)return '';
 const copy=c(lang),history=items.filter(x=>x.target_id===record.id),pending=pendingAmendment(history,record.id),terminal=type==='order'?['completed','cancelled'].includes(record.status):record.status==='cancelled';
 const historyMarkup=history.length?`<div class="amend-history"><strong>${esc(copy.history)}</strong>${history.map(a=>`<div class="amend-record"><b>${esc(copy[a.kind])} · ${esc(requestStatus(a,lang))}</b>${a.after_data?`<p>${esc(copy.after)}: ${esc(dataSummary(a.after_data,lang))}</p>`:''}${!owner&&(a.status==='rejected'||a.proposal_data)&&a.reason_messages?.[lang]?`<p lang="${esc(lang)}">${esc(a.reason_messages[lang])}</p>`:''}${owner?ownerAudit(a):''}${proposalMarkup(a,lang,owner)}${owner&&a.reviewed_by?`<small>${esc(a.reviewed_by==='owner'?(ownerName[lang]||ownerName.en):a.reviewed_by)} · ${esc(new Date(a.reviewed_at).toLocaleString(lang))}</small>`:''}</div>`).join('')}</div>`:'';
 if(pending){const late=type==='order'&&['preparing','ready'].includes(record.status),pc=PROPOSAL_COPY[lang]||PROPOSAL_COPY.en;if(pending.proposal_status==='pending')return historyMarkup+`<p class="amend-note">${esc(pc.hold)}</p>${!owner?`<div class="inline-actions"><button class="button primary" data-offer-reply="${esc(pending.id)}" data-accept="true">${esc(pc.accept)}</button><button class="button" data-offer-reply="${esc(pending.id)}" data-accept="false">${esc(pc.decline)}</button></div><details class="amend-editor counter-editor"><summary>${esc((NEGOTIATION_COPY[lang]||NEGOTIATION_COPY.en).edit)}</summary><p>${esc((NEGOTIATION_COPY[lang]||NEGOTIATION_COPY.en).hint)}</p><form data-form="amend-counter" data-request="${esc(pending.id)}" data-type="${esc(type)}">${editInputs(type,pending.proposal_data,menu,lang,labels)}<p data-counter-error role="alert" tabindex="-1" hidden></p><button class="button primary">${esc((NEGOTIATION_COPY[lang]||NEGOTIATION_COPY.en).submit)}</button></form></details>`:''}`;return historyMarkup+`<p class="amend-note">${esc(late?copy.ownerOnly:copy.staffCan)} ${type==='order'?esc(copy.holding):''}</p>${owner?`<div class="inline-actions"><button class="button primary" data-amend-review="${esc(pending.id)}" data-approve="true">${esc(copy.approve)}</button>${rejectionForm(pending,lang,false,menu)}</div>`:''}`;}
 if(owner||terminal)return historyMarkup;
 const inputs=editInputs(type,record,menu,lang,labels);
 return historyMarkup+`<details class="amend-editor"><summary>${esc(copy.change)}</summary>${type==='order'?`<p>${esc(copy.editNote)}</p>`:''}<form data-form="amend-change" data-type="${type}" data-target="${esc(record.id)}">${inputs}<button class="button primary">${esc(copy.submit)}</button></form></details><button class="button" data-amend-cancel="${esc(record.id)}" data-type="${type}">${esc(copy.cancel)}</button>`;
}
export function staffAmendmentMarkup({items=[],record,type,lang='ko',member,menu=[]}){
 const copy=c(lang),history=items.filter(x=>x.target_id===record.id),a=pendingAmendment(history,record.id),n=NEGOTIATION_COPY[lang]||NEGOTIATION_COPY.en;
 const previous=history.filter(x=>x.id!==a?.id&&(x.proposal_data||x.parent_amendment_id)).map(x=>`<div class="amend-record">${x.parent_amendment_id?`<b>${esc(requestStatus(x,lang))}</b>${x.after_data?`<p>${esc(copy.after)}: ${esc(dataSummary(x.after_data,lang))}</p>`:''}`:''}${proposalMarkup(x,lang)}</div>`).join('');
 if(!a)return previous;
 const late=type==='order'&&['preparing','ready'].includes(record.status),canReview=member.role==='floor'&&!late&&(type==='order'?member.permissions.includes('ordersAccept'):member.permissions.includes('bookingsManage'));
 return `<div class="amend-record"><b>${esc(copy[a.kind])} · ${esc(a.proposal_status==='pending'?(PROPOSAL_COPY[lang]||PROPOSAL_COPY.en).pending:requestStatus(a,lang))}</b>${a.after_data?`<p>${esc(copy.after)}: ${esc(dataSummary(a.after_data,lang))}</p>`:''}${a.proposal_data?proposalMarkup(a,lang):`<p>${esc(late?copy.ownerOnly:copy.staffCan)}</p>`}${canReview&&!a.proposal_status?`<div class="inline-actions"><button class="button primary" data-staff-amend="${esc(a.id)}" data-approve="true">${esc(copy.approve)}</button>${rejectionForm(a,lang,true,menu)}</div>`:''}</div>${previous}`;
}
export function amendmentCopy(lang,key){return c(lang)[key]||key;}

export function syncOfferRequirements(form){if(!form?.elements.offer)return;for(const name of ['itemId','quantity','date','time'])if(form.elements[name])form.elements[name].required=form.elements.offer.checked;const button=form.querySelector('button[type=submit]');if(button)button.textContent=form.elements.offer.checked?button.dataset.offerLabel:button.dataset.rejectLabel;}
